(function(){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const views=()=>window.AURORA_CAR_VIEWS||[];
 const featured=['front-right','side-right','front','rear-right','exploded'];
 let current='front-right',timer=null,playing=false,ctx=null,sequence=0,visibility=null,intersection=null,inView=true;
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function hero(c){const v=views().find(v=>v.id===current)||views()[0];if(!v)return '';return `<section class="hero home-hero motion-hero"><div class="aurora-field" aria-hidden="true"><i></i><i></i><i></i></div><div class="speed-field" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="telemetry-grid" aria-hidden="true"></div><div class="container hero-inner"><div class="hero-copy"><div class="hero-kicker"><span></span>AURORA · PERFORMANCE & CULTURE</div><h1>Performance,<br><em>with proof.</em></h1><p>让热爱有方向，让每一次升级有依据。</p><div class="hero-actions"><a class="button primary" href="#lab"><span>探索性能对比<small>EXPLORE PERFORMANCE</small></span>${c.icon('chart')}</a><a class="button ghost" href="#community"><span>走进汽车文化<small>DISCOVER THE CULTURE</small></span>${c.icon('arrow')}</a></div><div class="hero-signature"><span class="signature-rule"></span><b>ENGINEERED BY PASSION.</b><span>深圳技术大学 · 极光车队</span></div></div><div class="car-stage"><div class="car-model"><span>AR–26</span><small>FORMULA STUDENT / E27</small></div><button class="car-image-button" data-car-open aria-label="打开 AR-26 赛车多视角图库"><img id="hero-car-image" src="${esc(v.src)}" alt="${esc(v.alt)}" fetchpriority="high" decoding="async"></button><div class="car-stage-caption"><span><i></i>AR-26 赛车视角 <small id="hero-car-angle">${esc(v.title)} / ${esc(v.en)}</small></span><button data-car-open class="car-expand" aria-label="浏览全部赛车图片">全视角 ${c.icon('expand')||'↗'}</button></div></div><div class="hero-bottom-note">PASSION IN MOTION. PRECISION IN EVERY CHOICE.</div><div class="car-control-bar" aria-label="选择赛车视角"><div class="car-thumbnails">${featured.map(id=>{const p=views().find(v=>v.id===id);return p?`<button data-car-view="${esc(id)}" class="${current===id?'active':''}" aria-pressed="${current===id}" aria-label="切换到${esc(p.title)}"><img src="${esc(p.thumb)}" alt="" decoding="async"><span>${esc(p.title)}</span></button>`:''}).join('')}</div><button class="car-play" data-car-play aria-pressed="false" aria-label="自动切换赛车视角"><span>▶</span><small>自动浏览</small></button></div></div></section>`}
 function updatePlayback(){document.querySelectorAll('[data-car-play]').forEach(b=>{b.setAttribute('aria-pressed',String(playing));b.setAttribute('aria-label',playing?'暂停自动切换':'自动切换赛车视角');b.innerHTML=playing?'<span>Ⅱ</span><small>暂停浏览</small>':'<span>▶</span><small>自动浏览</small>'});document.querySelector('.motion-hero')?.classList.toggle('is-playing',playing)}
 function schedule(){clearTimeout(timer);if(!playing||document.hidden||!inView||document.querySelector('#modal')?.open)return;timer=setTimeout(()=>{const list=views().slice(0,8),i=list.findIndex(v=>v.id===current);select(list[(i+1)%list.length].id,false);schedule()},6500)}
 function play(value){playing=value;updatePlayback();schedule()}
 async function select(id,manual=true){const v=views().find(v=>v.id===id);if(!v)return;if(manual)play(false);current=id;const stamp=++sequence;const img=document.querySelector('#hero-car-image');if(img){const pre=new Image();pre.src=v.src;try{await pre.decode()}catch{ return }if(stamp!==sequence||!img.isConnected)return;img.classList.add('is-changing');await new Promise(resolve=>setTimeout(resolve,reduced()?0:150));if(stamp!==sequence||!img.isConnected)return;img.src=v.src;img.alt=v.alt;img.classList.remove('is-changing');document.querySelector('#hero-car-angle').textContent=v.title+' / '+v.en;document.querySelectorAll('[data-car-view]').forEach(b=>{b.classList.toggle('active',b.dataset.carView===id);b.setAttribute('aria-pressed',String(b.dataset.carView===id))})}const dialog=document.querySelector('#modal');if(dialog?.open&&dialog.classList.contains('car-dialog'))updateDialog()}
 function dialogBody(){const v=views().find(v=>v.id===current)||views()[0],i=views().indexOf(v);return `<div class="car-dialog-media"><img src="${esc(v.src)}" alt="${esc(v.alt)}"><button class="lightbox-arrow previous" data-car-step="-1" aria-label="上一视角">←</button><button class="lightbox-arrow next" data-car-step="1" aria-label="下一视角">→</button></div><div class="car-dialog-caption"><strong>${esc(v.title)}<small>${esc(v.en)}</small></strong><span>${String(i+1).padStart(2,'0')} / ${views().length}</span></div><div class="car-dialog-views" aria-label="赛车全部视角">${views().map(p=>`<button data-car-view="${esc(p.id)}" aria-label="${esc(p.title)}" aria-pressed="${p.id===current}" class="${p.id===current?'active':''}"><img src="${esc(p.thumb)}" alt="" loading="lazy"><span>${esc(p.title)}</span></button>`).join('')}</div>`}
 function updateDialog(){const content=document.querySelector('#car-dialog-body');if(content)content.innerHTML=dialogBody()}
 function open(){if(!ctx)return;play(false);ctx.modal('AR-26 · 极光赛车',`<div id="car-dialog-body">${dialogBody()}</div>`);const d=document.querySelector('#modal');d.classList.remove('photo-dialog');d.classList.add('car-dialog')}
 function mount(c){ctx=c;if(c.route!=='home')return;current=views().find(v=>v.id===current)?.id||views()[0]?.id;playing=!reduced()&&(window.AuroraMotion?.enabled!==false);inView=true;updatePlayback();schedule();visibility=()=>schedule();document.addEventListener('visibilitychange',visibility);intersection=new IntersectionObserver(entries=>{inView=entries[0]?.isIntersecting??true;schedule()},{threshold:.12});const hero=document.querySelector('.motion-hero');if(hero)intersection.observe(hero);views().slice(0,5).forEach(v=>{const i=new Image();i.src=v.src})}
 function unmount(){clearTimeout(timer);playing=false;sequence++;intersection?.disconnect();if(visibility)document.removeEventListener('visibilitychange',visibility);visibility=null;ctx=null}
 document.addEventListener('click',e=>{const view=e.target.closest('[data-car-view]');if(view){select(view.dataset.carView);return}if(e.target.closest('[data-car-open]')){open();return}if(e.target.closest('[data-car-play]')){play(!playing);return}const step=e.target.closest('[data-car-step]');if(step){const i=views().findIndex(v=>v.id===current);select(views()[(i+Number(step.dataset.carStep)+views().length)%views().length].id)}});
 document.addEventListener('keydown',e=>{const d=document.querySelector('#modal');if(d?.open&&d.classList.contains('car-dialog')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=views().findIndex(v=>v.id===current);select(views()[(i+(e.key==='ArrowRight'?1:-1)+views().length)%views().length].id)}});
 document.querySelector('#modal')?.addEventListener('close',schedule);
 window.AuroraCar={hero,mount,unmount,setPlayback:value=>{if(document.querySelector('.motion-hero'))play(!!value)},inspect:()=>({current,playing,views:views().length})};
})();
